// The macros of Protocol Buffers that change how CDT parses the code generated by protoc and the code using its library, since its headers are not available.
// The macros that are attributes of the declarations are defined as empty, i.e., GOOGLE_PROTOBUF_ATTRIBUTE_SECTION_VARIABLE(protodesc_cold) in
// const uint32 TableStruct::offsets[] GOOGLE_PROTOBUF_ATTRIBUTE_SECTION_VARIABLE(protodesc_cold) = {...}; which CDT otherwise does not parse as a declaration.
// The macros that are statements or expressions, i.e., GOOGLE_PROTOBUF_GENERATED_MESSAGE_FIELD_OFFSET(T, f), GOOGLE_LONGLONG(x) or GOOGLE_DCHECK(x),
// are not defined, so that they are parsed as calls.
// The lines starting with // are removed before parsing.
// protobuf 3.x
#define GOOGLE_PROTOBUF_ATTRIBUTE_SECTION_VARIABLE(name)
#define GOOGLE_PROTOBUF_ATTRIBUTE_NOINLINE
#define GOOGLE_PROTOBUF_ATTRIBUTE_ALWAYS_INLINE
#define GOOGLE_PROTOBUF_ATTRIBUTE_COLD
#define GOOGLE_PROTOBUF_ATTRIBUTE_WEAK
#define GOOGLE_PROTOBUF_ATTRIBUTE_RETURNS_NONNULL
#define GOOGLE_PROTOBUF_DEPRECATED
#define GOOGLE_PROTOBUF_DEPRECATED_ATTR
#define GOOGLE_ATTRIBUTE_ALWAYS_INLINE
#define GOOGLE_ATTRIBUTE_NOINLINE
#define GOOGLE_ATTRIBUTE_DEPRECATED
#define LIBPROTOBUF_EXPORT
#define LIBPROTOC_EXPORT
// protobuf 3.8 and later
#define PROTOBUF_EXPORT
#define PROTOC_EXPORT
#define PROTOBUF_NOINLINE
#define PROTOBUF_ALWAYS_INLINE
#define PROTOBUF_COLD
#define PROTOBUF_SECTION_VARIABLE(name)
#define PROTOBUF_ATTRIBUTE_SECTION_VARIABLE(name)
#define PROTOBUF_ATTRIBUTE_NO_DESTROY
#define PROTOBUF_ATTRIBUTE_INIT_PRIORITY
#define PROTOBUF_ATTRIBUTE_INIT_PRIORITY1
#define PROTOBUF_ATTRIBUTE_INIT_PRIORITY2
#define PROTOBUF_ATTRIBUTE_WEAK
#define PROTOBUF_ATTRIBUTE_REINITIALIZES
#define PROTOBUF_ATTRIBUTE_STANDALONE_DEBUG
#define PROTOBUF_NODISCARD
#define PROTOBUF_MUST_USE_RESULT
#define PROTOBUF_FUTURE_ADD_NODISCARD
#define PROTOBUF_DEPRECATED
#define PROTOBUF_DEPRECATED_ENUM
#define PROTOBUF_DEPRECATED_MSG(message)
#define PROTOBUF_CONSTEXPR constexpr
#define PROTOBUF_CONSTINIT
#define PROTOBUF_FINAL final
#define PROTOBUF_NAMESPACE_ID google::protobuf
#define PROTOBUF_NAMESPACE_OPEN namespace google { namespace protobuf {
#define PROTOBUF_NAMESPACE_CLOSE } }
